import std/unittest
import std/options
import std/json
import core/json/json_utils

suite "Feature: JSON utility functions":

  test "Parse valid JSON string":
    let raw = "{\"a\": 1, \"b\": [true, null]}"
    let result = parseJsonOpt(raw)
    check result.isSome
    let node = result.get
    check node.kind == JObject
    check node["a"].getInt == 1
    check node["b"].kind == JArray
    check node["b"][0].getBool == true

  test "Parse invalid JSON string":
    let raw = "{invalid"
    let result = parseJsonOpt(raw)
    check result.isNone

  test "Parse empty string":
    let raw = ""
    let result = parseJsonOpt(raw)
    check result.isNone